"use strict";
const fs = require("fs");
const Module = require("module");
const path = require("path");
const first = require("./first");

// Every file Node resolves while this wrapper is in place passes through it.
const seen = [];
const realpathSync = fs.realpathSync;
fs.realpathSync = function watched(file, options) {
  seen.push(path.basename(String(file)));
  return realpathSync.call(this, file, options);
};
fs.realpathSync.native = realpathSync.native;
const second = require("./second");
fs.realpathSync = realpathSync;
const third = require("./third");

// The extension table's order decides which file `./pick` names.
const js = Module._extensions[".js"];
delete Module._extensions[".js"];
Module._extensions[".js"] = js;
const pick = require("./pick");

exports.report = () => [first.name, second.name, third.name, seen.join(","), pick.kind].join(" ");
